CREATE TABLE users(id UUID PRIMARY KEY,email VARCHAR(255) NOT NULL UNIQUE,login_id VARCHAR(100) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role VARCHAR(20) NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE students(user_id UUID PRIMARY KEY REFERENCES users(id),roll_no VARCHAR(50) NOT NULL UNIQUE,full_name VARCHAR(200) NOT NULL,phone VARCHAR(40),gender VARCHAR(30),father_name VARCHAR(200),mother_name VARCHAR(200),parent_phone VARCHAR(40),address TEXT,city VARCHAR(100),pincode VARCHAR(20),department VARCHAR(200),course VARCHAR(100),year_label VARCHAR(50),semester VARCHAR(30),section VARCHAR(30),date_of_birth DATE);
CREATE TABLE faculty(user_id UUID PRIMARY KEY REFERENCES users(id),full_name VARCHAR(200),designation VARCHAR(150),department VARCHAR(200),personal_email VARCHAR(255),phone VARCHAR(40),gender VARCHAR(30),qualification VARCHAR(255),age INTEGER,experience_years INTEGER);
CREATE TABLE college_classes(id UUID PRIMARY KEY,code VARCHAR(50) NOT NULL UNIQUE,label VARCHAR(150) NOT NULL,year_number INTEGER,section VARCHAR(30),semester VARCHAR(30));
CREATE TABLE subjects(id UUID PRIMARY KEY,college_class_id UUID NOT NULL REFERENCES college_classes(id),faculty_id UUID NOT NULL REFERENCES faculty(user_id),name VARCHAR(150) NOT NULL,code VARCHAR(50));
CREATE TABLE enrollments(id UUID PRIMARY KEY,student_id UUID NOT NULL REFERENCES students(user_id),college_class_id UUID NOT NULL REFERENCES college_classes(id),CONSTRAINT uq_enrollment UNIQUE(student_id,college_class_id));
CREATE TABLE attendance_records(id UUID PRIMARY KEY,student_id UUID NOT NULL REFERENCES students(user_id),college_class_id UUID NOT NULL REFERENCES college_classes(id),subject_id UUID NOT NULL REFERENCES subjects(id),marked_by_id UUID NOT NULL REFERENCES faculty(user_id),attendance_date DATE NOT NULL,period_number INTEGER NOT NULL,status VARCHAR(20) NOT NULL,updated_at TIMESTAMPTZ NOT NULL,CONSTRAINT uq_attendance UNIQUE(student_id,college_class_id,attendance_date,period_number));
CREATE TABLE calendar_events(id UUID PRIMARY KEY,title VARCHAR(200) NOT NULL,type VARCHAR(30) NOT NULL,start_date DATE NOT NULL,end_date DATE NOT NULL);
CREATE TABLE exam_slots(id UUID PRIMARY KEY,college_class_id UUID NOT NULL REFERENCES college_classes(id),exam_type VARCHAR(30) NOT NULL,subject VARCHAR(150) NOT NULL,code VARCHAR(50) NOT NULL,exam_date DATE NOT NULL);
CREATE TABLE password_reset_tokens(id UUID PRIMARY KEY,user_id UUID NOT NULL REFERENCES users(id),token_hash VARCHAR(255) NOT NULL UNIQUE,expires_at TIMESTAMPTZ NOT NULL,used_at TIMESTAMPTZ);
CREATE INDEX idx_attendance_student_date ON attendance_records(student_id,attendance_date);
CREATE INDEX idx_attendance_class_date_period ON attendance_records(college_class_id,attendance_date,period_number);
